const context = $('09 Prepare Notification Context').item.json;
const secret = $json || {};
return [{json: {...context, thikaa_api_token: secret.api_token || null, thikaa_signing_secret: secret.signing_secret || null, thikaa_tenant_identifier: secret.tenant_identifier || context.tenant_identifier || null}}];

const item = $json;
const vars = {patient_name: item.patient_name, clinic_name: item.clinic_name, doctor_name: item.doctor_name || 'الطبيب', service_name: item.service_name || '', appointment_date: item.appointment_scheduled_at ? new Date(item.appointment_scheduled_at).toLocaleDateString('ar-EG') : '', appointment_time: item.appointment_scheduled_at ? new Date(item.appointment_scheduled_at).toLocaleTimeString('ar-EG', {hour: '2-digit', minute: '2-digit'}) : '', offer_expires_at: item.offer_expires_at ? new Date(item.offer_expires_at).toLocaleString('ar-EG') : ''};
let message = item.body_template || '';
for (const [key, value] of Object.entries(vars)) message = message.replaceAll(`{{${key}}}`, value == null ? '' : String(value));
const channelMap = {whatsapp: item.patient_phone ? 'wa' : 'wd', messenger: 'fb', instagram: 'ig', telegram: 'tg'};
const recipient = item.channel_type === 'whatsapp' ? item.patient_phone : item.channel_conversation_id;
const providerReady = item.provider === 'thikaa' && !!(item.thikaa_tenant_identifier || item.tenant_identifier);
const recipientReady = !!recipient;
const messageReady = message.trim().length > 0;
const ready = providerReady && recipientReady && messageReady;
const preError = !providerReady ? 'PROVIDER_ADAPTER_NOT_CONFIGURED' : (!recipientReady ? 'RECIPIENT_NOT_AVAILABLE' : (!messageReady ? 'EMPTY_RENDERED_MESSAGE' : null));
return [{json: {...item, rendered_message: message, recipient, thikaa_channel: channelMap[item.channel_type] || null, thikaa_url: item.thikaa_tenant_identifier ? `https://thikaa.com/${item.thikaa_tenant_identifier}/api/messaging/?action=send` : null, ready_to_send: ready, pre_error_category: preError}}];

const raw = $json && typeof $json === 'object' ? $json : {};
let context = {};
try { context = $('12 Render Four Channel Provider Request').item.json || {}; } catch (_) { context = {}; }
const merged = {...context, ...raw};
let body = raw.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (_) { body = {}; } }
if (!body || typeof body !== 'object' || Object.keys(body).length === 0) body = raw;
body = body && typeof body === 'object' ? body : {};
const explicitStatus = Number(raw.statusCode ?? raw.status_code ?? raw.status ?? 0);
const providerSuccess = raw.ok === true || raw.delivery === 'sent' || body.ok === true || body.delivery === 'sent';
const statusCode = explicitStatus || (providerSuccess ? 200 : 0);
const providerMessageId = body.message_id || body.id || raw.message_id || raw.provider_message_id || null;
const transportOk = (statusCode >= 200 && statusCode < 300 || providerSuccess) && raw.error == null && body.ok !== false;
let outcome; let errorCategory = null; let retryAfter = null;
if (transportOk && providerMessageId) outcome = 'ACCEPTED';
else if (transportOk && !providerMessageId) { outcome = 'AMBIGUOUS'; errorCategory = 'MISSING_PROVIDER_MESSAGE_ID'; }
else if (statusCode === 429 || statusCode >= 500 || raw.error) { outcome = 'RETRYABLE_FAILURE'; errorCategory = statusCode === 429 ? 'RATE_LIMITED' : 'TRANSPORT_ERROR'; retryAfter = statusCode === 429 ? 60 : 30; }
else { outcome = 'PERMANENT_FAILURE'; errorCategory = 'PROVIDER_HTTP_' + (statusCode || 'NO_RESPONSE'); }
function sqlLit(value) { if (value === null || value === undefined || value === '') return 'NULL'; return String.fromCharCode(39) + String(value).replaceAll(String.fromCharCode(39), String.fromCharCode(39,39)) + String.fromCharCode(39); }
const meta = JSON.stringify({status_code: statusCode, provider_body: body, channel_type: merged.channel_type || null});
const finishQuery = 'SELECT public.notification_finish_attempt(' + sqlLit(merged.job_id) + '::uuid, ' + sqlLit(merged.attempt_id) + '::uuid, ' + sqlLit('n8n:notifications:v3:dispatcher') + ', ' + sqlLit(outcome) + ', ' + sqlLit(providerMessageId) + '::text, ' + (statusCode || 'NULL') + '::integer, ' + sqlLit(errorCategory) + ', ' + (retryAfter || 'NULL') + '::integer, ' + sqlLit(meta) + '::jsonb) AS final_status;';
return [{json: {...merged, finish_query: finishQuery}}];

function sqlLit(value) { if (value === null || value === undefined || value === '') return 'NULL'; return String.fromCharCode(39) + String(value).replaceAll(String.fromCharCode(39), String.fromCharCode(39,39)) + String.fromCharCode(39); }
const meta = JSON.stringify({reason: $json.pre_error_category, channel_type: $json.channel_type || null});
const finishQuery = 'SELECT public.notification_finish_attempt(' + sqlLit($json.job_id) + '::uuid, ' + sqlLit($json.attempt_id) + '::uuid, ' + sqlLit('n8n:notifications:v3:dispatcher') + ', ' + sqlLit('PERMANENT_FAILURE') + ', NULL, NULL, ' + sqlLit($json.pre_error_category || 'PRE_SEND_VALIDATION_FAILED') + ', NULL, ' + sqlLit(meta) + '::jsonb) AS final_status;';
return [{json: {...$json, finish_query: finishQuery}}];
